sql.oracle:
DECLARE
    v_antiga NUMBER;
    v_nova   NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_antiga FROM user_tables WHERE table_name = 'BCO_CADCREDENCIAL';
    SELECT COUNT(*) INTO v_nova   FROM user_tables WHERE table_name = 'BCO_PARAMBANCO';
    IF v_antiga = 1 AND v_nova = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE BCO_CADCREDENCIAL RENAME TO BCO_PARAMBANCO';
    END IF;
END;
